        }
        .header {
            background-color: #333;
            color: #fff;
            padding: 1em;
            text-align: center;
        }
        .menu {
            padding: 2em;
        }
        .menu-item {
            margin-bottom: 1em;
            padding: 1em;
            border-bottom: 1px solid #ddd;
        }
        .menu-item-price {
            font-weight: bold;
        }
    </style>
</head>
<body>
    <div class="header">
        <h1>蜀大侠火锅</h1>
        <a href="restaurant-list.html">返回餐厅列表</a>
    </div>
    <div class="menu">
        <h2>菜单</h2>
        <div class="menu-item">
            <span>麻辣火锅</span> - <span class="menu-item-price">¥ 25.99</span>
        </div>
        <div class="menu-item">
            <span>清汤火锅</span> - <span class="menu-item-price">¥ 22.99</span>
        </div>
        <div class="menu-item">
            <span>毛肚</span> - <span class="menu-item-price">¥ 18.99</span>
        </div>
        <button onclick="location.href='order-summary.html'">立即订购</button>
    </div>
</body>
</html>
